insert into public.countries (iso2, region, wiki, capital_uk, capital_pl, intro_uk, intro_pl, best_months, daily_cost, tags, airport_code, airport_name, airport_lat, airport_lng) values
  ('AD', 'west', 'Andorra', 'Андорра-ла-Велья', 'Andora', 'Гірська країна в Піренеях з лижними курортами, шопінгом без мит і термальними спа. Взимку — сноуборд, улітку — хайкінг.', 'Górskie państwo w Pirenejach z ośrodkami narciarskimi, zakupami bez cła i termami. Zimą snowboard, latem trekking.', array[1, 2, 3, 7, 8, 12]::smallint[], 65, array['mountains', 'nature', 'family', 'comfort']::text[], 'BCN', 'Barcelona El Prat (+ автобус 3 год)', 41.3, 2.08),
  ('AL', 'balkans', 'Albania', 'Тирана', 'Tirana', 'Бірюзове Іонічне море, османські містечка на схилах гір і одні з найдоступніших цін у Європі. Албанія — секрет, який швидко перестає бути секретом.', 'Turkusowe Morze Jońskie, osmańskie miasteczka na zboczach gór i jedne z najniższych cen w Europie. Albania to sekret, który szybko przestaje być sekretem.', array[5, 6, 7, 8, 9]::smallint[], 30, array['sea', 'history', 'nature', 'food', 'mountains']::text[], 'TIA', 'Tirana Nënë Tereza', 41.41, 19.72),
  ('AT', 'west', 'Austria', 'Відень', 'Wiedeń', 'Імперський Відень, Моцартів Зальцбург, альпійські озера влітку й гірськолижні курорти взимку. Австрія — це елегантність і свіже гірське повітря.', 'Cesarski Wiedeń, Salzburg Mozarta, alpejskie jeziora latem i stoki narciarskie zimą. Austria to elegancja i świeże górskie powietrze.', array[5, 6, 7, 8, 9, 12, 1, 2]::smallint[], 80, array['mountains', 'history', 'city', 'nature', 'comfort']::text[], 'VIE', 'Vienna International', 48.11, 16.57),
  ('BA', 'balkans', 'Bosnia and Herzegovina', 'Сараєво', 'Sarajewo', 'Старий міст у Мостарі, кав''ярні Сараєва, де Схід зустрічається із Заходом, і смарагдові водоспади. Боснія й Герцеговина дивує на кожному кроці.', 'Stary Most w Mostarze, kawiarnie Sarajewa, gdzie Wschód spotyka Zachód, i szmaragdowe wodospady. Bośnia i Hercegowina zaskakuje na każdym kroku.', array[5, 6, 7, 8, 9]::smallint[], 30, array['history', 'nature', 'food', 'mountains']::text[], 'SJJ', 'Sarajevo International', 43.82, 18.33),
  ('BE', 'west', 'Belgium', 'Брюссель', 'Bruksela', 'Шоколад, вафлі, сотні сортів пива й середньовічні міста, наче з листівки. Бельгія маленька, але кожне місто тут — окрема пригода.', 'Czekolada, gofry, setki gatunków piwa i średniowieczne miasta jak z pocztówki. Belgia jest mała, ale każde miasto to osobna przygoda.', array[4, 5, 6, 7, 8, 9, 12]::smallint[], 80, array['city', 'history', 'food', 'couples']::text[], 'BRU', 'Brussels Airport', 50.9, 4.48),
  ('BG', 'east', 'Bulgaria', 'Софія', 'Sofia', 'Пляжі Чорного моря, гірськолижний Банско, Рильський монастир і одні з найнижчих цін у ЄС. Болгарія чудово підходить для сімейного відпочинку.', 'Plaże Morza Czarnego, narciarskie Bansko, Monastyr Rylski i jedne z najniższych cen w UE. Bułgaria świetnie nadaje się na rodzinny wypoczynek.', array[1, 2, 6, 7, 8, 9]::smallint[], 35, array['sea', 'mountains', 'history', 'family', 'food']::text[], 'SOF', 'Sofia Airport', 42.7, 23.41),
  ('CH', 'west', 'Switzerland', 'Берн', 'Berno', 'Сніжні вершини, кришталеві озера, панорамні потяги й найсмачніший шоколад. Швейцарія дорога, але кожен франк тут вартий краєвидів.', 'Ośnieżone szczyty, krystaliczne jeziora, panoramiczne pociągi i najlepsza czekolada. Szwajcaria jest droga, ale każdy frank jest wart tych widoków.', array[1, 2, 3, 6, 7, 8, 9, 12]::smallint[], 130, array['mountains', 'nature', 'comfort', 'couples', 'city']::text[], 'ZRH', 'Zürich Airport', 47.46, 8.55),
  ('CY', 'south', 'Cyprus', 'Нікосія', 'Nikozja', 'Острів Афродіти з 340 сонячними днями на рік, блакитними лагунами й античними руїнами. Кіпр — ідеальне море з квітня по листопад.', 'Wyspa Afrodyty z 340 słonecznymi dniami w roku, błękitnymi lagunami i antycznymi ruinami. Cypr to idealne morze od kwietnia do listopada.', array[4, 5, 6, 7, 8, 9, 10, 11]::smallint[], 60, array['sea', 'history', 'nightlife', 'family', 'comfort']::text[], 'LCA', 'Larnaca International', 34.88, 33.63),
  ('CZ', 'central', 'Czech Republic', 'Прага', 'Praga', 'Готичні шпилі Праги, чеське пиво за копійки й замки на кожному пагорбі. Чехія — одна з найкрасивіших і найдоступніших країн Європи.', 'Gotyckie iglice Pragi, tanie czeskie piwo i zamki na każdym wzgórzu. Czechy to jeden z najpiękniejszych i najtańszych krajów Europy.', array[4, 5, 6, 7, 8, 9, 12]::smallint[], 50, array['city', 'history', 'food', 'nightlife', 'couples']::text[], 'PRG', 'Praha Václav Havel', 50.1, 14.26),
  ('DE', 'west', 'Germany', 'Берлін', 'Berlin', 'Казкові замки, різдвяні ярмарки, пивні сади й найкращі музеї Європи. Німеччина однаково добре підходить для міських вихідних і подорожі Альпами.', 'Bajkowe zamki, jarmarki bożonarodzeniowe, ogródki piwne i jedne z najlepszych muzeów Europy. Niemcy sprawdzą się zarówno na miejski weekend, jak i na wyprawę w Alpy.', array[5, 6, 7, 8, 9, 12]::smallint[], 75, array['city', 'history', 'food', 'nightlife', 'mountains', 'family']::text[], 'BER', 'Berlin Brandenburg', 52.36, 13.5),
  ('DK', 'north', 'Denmark', 'Копенгаген', 'Kopenhaga', 'Кольорова набережна Нюгавн, «хюґе», велосипеди й батьківщина LEGO. Данія — затишна країна дизайну та казок Андерсена.', 'Kolorowe nabrzeże Nyhavn, „hygge”, rowery i ojczyzna LEGO. Dania to przytulny kraj designu i baśni Andersena.', array[5, 6, 7, 8, 12]::smallint[], 100, array['city', 'family', 'food', 'sea', 'couples']::text[], 'CPH', 'Copenhagen Kastrup', 55.62, 12.65),
  ('EE', 'north', 'Estonia', 'Таллінн', 'Tallinn', 'Середньовічний Таллінн, болота й ліси, острови Балтики та цифрова держава майбутнього. Естонія — компактна й дуже зручна для подорожі.', 'Średniowieczny Tallinn, bagna i lasy, bałtyckie wyspy i cyfrowe państwo przyszłości. Estonia jest kompaktowa i bardzo wygodna w podróży.', array[5, 6, 7, 8, 12]::smallint[], 55, array['history', 'city', 'nature', 'sea']::text[], 'TLL', 'Tallinn Lennart Meri', 59.41, 24.83),
  ('ES', 'south', 'Spain', 'Мадрид', 'Madryt', 'Сонце понад 300 днів на рік, фламенко, тапас до пізньої ночі та архітектура Гауді. Іспанія вміє жити повільно і смачно.', 'Ponad 300 słonecznych dni w roku, flamenco, tapas do późnej nocy i architektura Gaudíego. Hiszpania umie żyć powoli i smacznie.', array[4, 5, 6, 9, 10]::smallint[], 65, array['sea', 'city', 'food', 'nightlife', 'history']::text[], 'BCN', 'Barcelona-El Prat', 41.3, 2.08),
  ('FI', 'north', 'Finland', 'Гельсінкі', 'Helsinki', 'Тисячі озер, сауни, Лапландія з Санта-Клаусом і білі ночі. Фінляндія — найкраще місце для зимової казки.', 'Tysiące jezior, sauny, Laponia ze Świętym Mikołajem i białe noce. Finlandia to najlepsze miejsce na zimową bajkę.', array[1, 2, 3, 6, 7, 8, 12]::smallint[], 90, array['nature', 'family', 'couples', 'comfort', 'city']::text[], 'HEL', 'Helsinki-Vantaa', 60.32, 24.96),
  ('FR', 'west', 'France', 'Париж', 'Paryż', 'Париж, Лазурний берег, лавандові поля Провансу й тисяча сортів сиру. Франція — найвідвідуваніша країна світу, і на те є причини.', 'Paryż, Lazurowe Wybrzeże, lawendowe pola Prowansji i tysiąc gatunków sera. Francja to najczęściej odwiedzany kraj świata — i nie bez powodu.', array[4, 5, 6, 9]::smallint[], 85, array['city', 'food', 'history', 'sea', 'couples', 'mountains']::text[], 'CDG', 'Paris Charles de Gaulle', 49.01, 2.55),
  ('GB', 'west', 'United Kingdom', 'Лондон', 'Londyn', 'Королівські палаци, шотландські замки, пабові традиції та безкоштовні музеї світового рівня. Велика Британія — це чотири країни в одній подорожі.', 'Królewskie pałace, szkockie zamki, tradycje pubowe i darmowe muzea światowej klasy. Wielka Brytania to cztery kraje w jednej podróży.', array[5, 6, 7, 8, 9]::smallint[], 95, array['city', 'history', 'nature', 'nightlife', 'mountains']::text[], 'LHR', 'London Heathrow', 51.47, -0.45),
  ('GR', 'south', 'Greece', 'Афіни', 'Ateny', 'Тисячі островів, білі будиночки з синіми дверима, античні храми та свіжа риба на березі. Греція — класика літнього відпочинку.', 'Tysiące wysp, białe domki z niebieskimi drzwiami, antyczne świątynie i świeża ryba nad brzegiem. Grecja to klasyka letnich wakacji.', array[5, 6, 7, 8, 9, 10]::smallint[], 60, array['sea', 'history', 'food', 'couples', 'nature']::text[], 'ATH', 'Athens Eleftherios Venizelos', 37.94, 23.94),
  ('HR', 'balkans', 'Croatia', 'Загреб', 'Zagrzeb', 'Понад тисяча островів, кришталева Адріатика, римські палаци та бірюзові озера Плітвіце. Хорватія — ідеальне поєднання моря та історії.', 'Ponad tysiąc wysp, krystaliczny Adriatyk, rzymskie pałace i turkusowe Jeziora Plitwickie. Chorwacja to idealne połączenie morza i historii.', array[5, 6, 7, 8, 9]::smallint[], 60, array['sea', 'history', 'nature', 'couples']::text[], 'SPU', 'Split Airport', 43.54, 16.3),
  ('HU', 'central', 'Hungary', 'Будапешт', 'Budapeszt', 'Термальні купальні, руїн-бари, гуляш і найкрасивіший парламент Європи. Угорщина — це не лише Будапешт, а й озеро Балатон та винні долини.', 'Łaźnie termalne, ruin bary, gulasz i najpiękniejszy parlament Europy. Węgry to nie tylko Budapeszt, ale i Balaton oraz winne doliny.', array[4, 5, 6, 7, 8, 9]::smallint[], 50, array['city', 'nightlife', 'food', 'history', 'comfort']::text[], 'BUD', 'Budapest Ferenc Liszt', 47.44, 19.26),
  ('IE', 'west', 'Republic of Ireland', 'Дублін', 'Dublin', 'Зелені пагорби, скелі Мохер, живий фольк у пабах і замки біля океану. Ірландія — країна легенд, дощу й тепла людей.', 'Zielone wzgórza, klify Moher, muzyka folk na żywo w pubach i zamki nad oceanem. Irlandia to kraj legend, deszczu i ciepła ludzi.', array[5, 6, 7, 8, 9]::smallint[], 90, array['nature', 'city', 'nightlife', 'history']::text[], 'DUB', 'Dublin Airport', 53.43, -6.27),
  ('IS', 'north', 'Iceland', 'Рейк''явік', 'Reykjavik', 'Вулкани, гейзери, льодовики, водоспади й північне сяйво — Ісландія схожа на іншу планету. Найкраще її досліджувати на машині.', 'Wulkany, gejzery, lodowce, wodospady i zorza polarna — Islandia przypomina inną planetę. Najlepiej zwiedzać ją samochodem.', array[1, 2, 3, 6, 7, 8, 9]::smallint[], 120, array['nature', 'mountains', 'couples', 'comfort']::text[], 'KEF', 'Keflavík International', 63.99, -22.62),
  ('IT', 'south', 'Italy', 'Рим', 'Rzym', 'Римські руїни, ренесансні шедеври, кольорові селища над морем і паста, яку в кожному регіоні готують по-своєму. Італія — це країна, куди повертаються.', 'Rzymskie ruiny, renesansowe arcydzieła, kolorowe miasteczka nad morzem i makaron, który w każdym regionie robi się inaczej. Do Włoch się wraca.', array[4, 5, 6, 9, 10]::smallint[], 75, array['history', 'food', 'sea', 'city', 'couples']::text[], 'FCO', 'Roma Fiumicino', 41.8, 12.25),
  ('LI', 'west', 'Liechtenstein', 'Вадуц', 'Vaduz', 'Крихітне князівство між Швейцарією та Австрією з княжим замком, виноградниками та альпійськими стежками. Країну можна пройти пішки за день.', 'Maleńkie księstwo między Szwajcarią a Austrią z zamkiem książęcym, winnicami i alpejskimi szlakami. Kraj można przejść pieszo w jeden dzień.', array[1, 2, 6, 7, 8, 9]::smallint[], 120, array['mountains', 'nature', 'comfort', 'couples']::text[], 'ZRH', 'Zürich Airport (+ потяг 1,5 год)', 47.46, 8.55),
  ('LT', 'north', 'Lithuania', 'Вільнюс', 'Wilno', 'Барокове старе місто Вільнюса, замок на озері в Тракаї та дюни Куршської коси. Литва — тепла, зелена й дуже близька до Польщі.', 'Barokowe stare miasto Wilna, zamek na jeziorze w Trokach i wydmy Mierzei Kurońskiej. Litwa jest ciepła, zielona i bardzo bliska Polsce.', array[5, 6, 7, 8, 9, 12]::smallint[], 45, array['history', 'city', 'sea', 'nature', 'food']::text[], 'VNO', 'Vilnius International', 54.63, 25.29),
  ('LU', 'west', 'Luxembourg', 'Люксембург', 'Luksemburg', 'Фортеця на скелях, казкові долини й безкоштовний громадський транспорт по всій країні. Люксембург — ідеальний для коротких вихідних.', 'Twierdza na skałach, bajkowe doliny i darmowa komunikacja publiczna w całym kraju. Luksemburg jest idealny na krótki weekend.', array[5, 6, 7, 8, 9]::smallint[], 90, array['history', 'nature', 'city', 'couples', 'comfort']::text[], 'LUX', 'Luxembourg Findel', 49.63, 6.21),
  ('LV', 'north', 'Latvia', 'Рига', 'Ryga', 'Ар-нуво Риги, дюни Юрмали, середньовічні замки й соснові ліси. Латвія поєднує столичний шарм і тихий балтійський відпочинок.', 'Secesja Rygi, wydmy Jurmały, średniowieczne zamki i sosnowe lasy. Łotwa łączy stołeczny urok z cichym bałtyckim wypoczynkiem.', array[5, 6, 7, 8, 12]::smallint[], 50, array['city', 'history', 'sea', 'nature', 'nightlife']::text[], 'RIX', 'Riga International', 56.92, 23.97),
  ('MD', 'east', 'Moldova', 'Кишинів', 'Kiszyniów', 'Країна вина з найбільшими винними підвалами світу, печерними монастирями й гостинністю. Молдова — несподіване відкриття для гурманів.', 'Kraj wina z największymi piwnicami na świecie, skalnymi monastyrami i gościnnością. Mołdawia to zaskakujące odkrycie dla smakoszy.', array[5, 6, 9, 10]::smallint[], 30, array['food', 'history', 'nature', 'couples']::text[], 'RMO', 'Chișinău International', 46.93, 28.93),
  ('ME', 'balkans', 'Montenegro', 'Подгориця', 'Podgorica', 'Маленька країна з великими горами: фіорд Котора, гірські озера Дурмітора й пляжі Будви за кілька годин один від одного.', 'Mały kraj z wielkimi górami: fiord Kotoru, górskie jeziora Durmitoru i plaże Budvy w odległości kilku godzin.', array[5, 6, 7, 8, 9]::smallint[], 45, array['sea', 'mountains', 'nature', 'history']::text[], 'TIV', 'Tivat Airport', 42.4, 18.72),
  ('MK', 'balkans', 'North Macedonia', 'Скоп''є', 'Skopje', 'Охридське озеро — одне з найстаріших у світі, древні церкви, гори й найдоступніші ціни на Балканах. Північна Македонія — тиха перлина регіону.', 'Jezioro Ochrydzkie, jedno z najstarszych na świecie, dawne cerkwie, góry i najniższe ceny na Bałkanach. Macedonia Północna to cicha perła regionu.', array[5, 6, 7, 8, 9]::smallint[], 28, array['nature', 'history', 'sea', 'food', 'family']::text[], 'SKP', 'Skopje International', 41.96, 21.62),
  ('MT', 'south', 'Malta', 'Валетта', 'Valletta', 'Лицарські фортеці, Блакитна лагуна й кіно-локації «Гри престолів». Мальта — маленький острів з 7000 років історії.', 'Twierdze rycerskie, Błękitna Laguna i plenery „Gry o tron”. Malta to mała wyspa z 7000 lat historii.', array[4, 5, 6, 7, 8, 9, 10]::smallint[], 60, array['sea', 'history', 'nightlife', 'couples']::text[], 'MLA', 'Malta International', 35.86, 14.48),
  ('NL', 'west', 'Netherlands', 'Амстердам', 'Amsterdam', 'Канали, велосипеди, тюльпанові поля й музеї Ван Гога та Рембрандта. Нідерланди легко об''їхати за тиждень потягом.', 'Kanały, rowery, pola tulipanów i muzea Van Gogha oraz Rembrandta. Holandię łatwo objechać pociągiem w tydzień.', array[4, 5, 6, 7, 8, 9]::smallint[], 85, array['city', 'history', 'nightlife', 'nature', 'couples']::text[], 'AMS', 'Amsterdam Schiphol', 52.31, 4.76),
  ('NO', 'north', 'Norway', 'Осло', 'Oslo', 'Фіорди, водоспади, північне сяйво взимку й сонце опівночі влітку. Норвегія — для тих, хто шукає природу у найвищому її прояві.', 'Fiordy, wodospady, zorza polarna zimą i słońce o północy latem. Norwegia jest dla tych, którzy szukają natury w najlepszym wydaniu.', array[6, 7, 8, 12, 1, 2]::smallint[], 110, array['nature', 'mountains', 'sea', 'comfort']::text[], 'OSL', 'Oslo Gardermoen', 60.19, 11.1),
  ('PL', 'central', 'Poland', 'Варшава', 'Warszawa', 'Від середньовічного Кракова до балтійських дюн і Татр — Польща поєднує історію, природу та сучасні міста з чудовою їжею за розумні гроші.', 'Od średniowiecznego Krakowa po bałtyckie wydmy i Tatry — Polska łączy historię, przyrodę i nowoczesne miasta z świetnym jedzeniem w rozsądnych cenach.', array[5, 6, 7, 8, 9]::smallint[], 45, array['history', 'city', 'food', 'mountains', 'sea']::text[], 'KRK', 'Kraków-Balice', 50.08, 19.78),
  ('PT', 'south', 'Portugal', 'Лісабон', 'Lizbona', 'Жовті трамваї Лісабона, портвейн у Порту, скелі Алгарве та океанські хвилі для серферів. Португалія — тепла, спокійна й неймовірно фотогенічна.', 'Żółte tramwaje Lizbony, porto w Porto, klify Algarve i oceaniczne fale dla surferów. Portugalia jest ciepła, spokojna i niesamowicie fotogeniczna.', array[4, 5, 6, 9, 10]::smallint[], 60, array['sea', 'city', 'food', 'history', 'nature']::text[], 'LIS', 'Lisbon Humberto Delgado', 38.77, -9.13),
  ('RO', 'east', 'Romania', 'Бухарест', 'Bukareszt', 'Замки Трансильванії, мальовничі монастирі, дельта Дунаю й Карпати. Румунія — країна легенд і неймовірної природи за доступними цінами.', 'Zamki Transylwanii, malowane monastyry, delta Dunaju i Karpaty. Rumunia to kraj legend i niesamowitej przyrody w przystępnych cenach.', array[5, 6, 7, 8, 9, 10]::smallint[], 40, array['history', 'mountains', 'nature', 'food', 'family']::text[], 'OTP', 'Bucharest Henri Coandă', 44.57, 26.08),
  ('RS', 'balkans', 'Serbia', 'Белград', 'Belgrad', 'Нічне життя Белграда, фортеці на Дунаї, монастирі та щедра балканська кухня. Сербія вражає гостинністю й енергією.', 'Nocne życie Belgradu, twierdze nad Dunajem, monastery i obfita bałkańska kuchnia. Serbia zachwyca gościnnością i energią.', array[4, 5, 6, 7, 8, 9]::smallint[], 35, array['city', 'nightlife', 'food', 'history', 'mountains']::text[], 'BEG', 'Belgrade Nikola Tesla', 44.82, 20.31),
  ('SE', 'north', 'Sweden', 'Стокгольм', 'Sztokholm', 'Стокгольм на 14 островах, червоні дерев''яні будиночки, Лапландія з північним сяйвом. Швеція — це природа, дизайн і фіка.', 'Sztokholm na 14 wyspach, czerwone drewniane domki, Laponia z zorzą polarną. Szwecja to przyroda, design i fika.', array[1, 2, 3, 6, 7, 8, 12]::smallint[], 95, array['nature', 'city', 'sea', 'couples', 'family']::text[], 'ARN', 'Stockholm Arlanda', 59.65, 17.92),
  ('SI', 'central', 'Slovenia', 'Любляна', 'Lublana', 'Озеро Блед з островом-церквою, смарагдова річка Соча, печери й Адріатика — і все це за дві години їзди. Словенія — маленька зелена казка.', 'Jezioro Bled z wyspą-kościołem, szmaragdowa Soča, jaskinie i Adriatyk — wszystko w dwie godziny jazdy. Słowenia to mała zielona bajka.', array[5, 6, 7, 8, 9]::smallint[], 60, array['nature', 'mountains', 'sea', 'couples', 'city']::text[], 'LJU', 'Ljubljana Jože Pučnik', 46.22, 14.46),
  ('SK', 'central', 'Slovakia', 'Братислава', 'Bratysława', 'Високі Татри, печери, термальні купальні та компактна Братислава на Дунаї. Словаччина — недооцінена перлина для активного відпочинку.', 'Tatry Wysokie, jaskinie, kąpieliska termalne i kameralna Bratysława nad Dunajem. Słowacja to niedoceniana perła aktywnego wypoczynku.', array[1, 2, 6, 7, 8, 9, 12]::smallint[], 45, array['mountains', 'nature', 'history', 'family']::text[], 'BTS', 'Bratislava M. R. Štefánik', 48.17, 17.21),
  ('UA', 'east', 'Ukraine', 'Київ', 'Kijów', 'Країна золотоверхих соборів, Карпатських полонин і чорноморського узбережжя. Україна дивує поєднанням тисячолітньої історії, гостинності та кухні, яку хочеться пробувати знову й знову.', 'Kraj złotych kopuł, karpackich połonin i czarnomorskiego wybrzeża. Ukraina zaskakuje połączeniem tysiącletniej historii, gościnności i kuchni, do której chce się wracać.', array[5, 6, 7, 8, 9]::smallint[], 35, array['history', 'food', 'city', 'mountains']::text[], 'RZE', 'Rzeszów-Jasionka (Польща) + поїзд', 50.11, 22.02),
  ('XK', 'balkans', 'Kosovo', 'Приштина', 'Prisztina', 'Наймолодша країна Європи з енергійною столицею, османською Прізреном і горами Ругова. Тут дуже дешево й дуже гостинно.', 'Najmłodszy kraj Europy z energiczną stolicą, osmańskim Prizrenem i górami Rugova. Jest tu bardzo tanio i bardzo gościnnie.', array[5, 6, 7, 8, 9]::smallint[], 25, array['history', 'mountains', 'nature', 'food']::text[], 'PRN', 'Pristina Adem Jashari', 42.57, 21.04)
